Uma solução eficiente e correta em Java para o problema.

### Abordagem

O problema nos pede para encontrar a primeira string $S_k$ que seja substring da concatenação de duas strings anteriores $S_a S_b$ ($a, b < k$).

Uma string $S_k$ é substring de $S_a S_b$ se e somente se pelo menos uma das seguintes condições for satisfeita:
1. $S_k$ está contida inteiramente em $S_a$ ou $S_b$ (ou seja, $S_k$ é substring de alguma string anterior).
2. $S_k$ cruza a fronteira entre $S_a$ e $S_b$. Isso significa que existe algum ponto de divisão $i$ ($1 \le i < |S_k|$) tal que o prefixo $S_k[0 \dots i-1]$ é um sufixo de alguma string anterior $S_a$, e o sufixo $S_k[i \dots |S_k|-1]$ é um prefixo de alguma string anterior $S_b$.

Como as strings têm comprimento de no máximo 10 caracteres minúsculos ('a' a 'z'), podemos codificar qualquer substring de até 12 caracteres de forma única e sem colisões em um inteiro de 64 bits (`long`), usando 5 bits por caractere. Para máxima velocidade e economia de memória, utilizamos tabelas hash com endereçamento aberto (*open addressing*).

### Código em Java

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {

    // Tabela Hash simples e rápida para tipos primitivos long (Open Addressing)
    static class LongHashSet {
        private final int mask;
        private final long[] table;
        private boolean hasZero = false;

        public LongHashSet(int capacityPowerOfTwo) {
            this.mask = capacityPowerOfTwo - 1;
            this.table = new long[capacityPowerOfTwo];
        }

        private int hash(long key) {
            key ^= (key >>> 33);
            key *= 0xff51afd7ed558ccdL;
            key ^= (key >>> 33);
            key *= 0xc4ceb9fe1a85ec53L;
            key ^= (key >>> 33);
            return (int) (key & mask);
        }

        public void add(long key) {
            if (key == 0) {
                hasZero = true;
                return;
            }
            int idx = hash(key);
            while (table[idx] != 0) {
                if (table[idx] == key) return;
                idx = (idx + 1) & mask;
            }
            table[idx] = key;
        }

        public boolean contains(long key) {
            if (key == 0) return hasZero;
            int idx = hash(key);
            while (table[idx] != 0) {
                if (table[idx] == key) return true;
                idx = (idx + 1) & mask;
            }
            return false;
        }
    }

    // Codifica uma substring em um long (5 bits por caractere)
    private static long encode(String s, int start, int end) {
        long code = 0;
        for (int i = start; i < end; i++) {
            code = (code << 5) | (s.charAt(i) - 'a' + 1);
        }
        return code;
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        String[] s = new String[n];
        for (int i = 0; i < n; i++) {
            s[i] = scanner.next();
        }

        // Capacidades dimensionadas para potências de 2 com fator de carga seguro
        LongHashSet prefixes = new LongHashSet(1 << 18);   // ~100k elementos
        LongHashSet suffixes = new LongHashSet(1 << 18);   // ~100k elementos
        LongHashSet substrings = new LongHashSet(1 << 20); // ~550k elementos

        for (int k = 0; k < n; k++) {
            String current = s[k];
            int len = current.length();

            if (k > 0) {
                boolean invalid = false;

                // Caso 1: S_k é substring de alguma string anterior
                long fullCode = encode(current, 0, len);
                if (substrings.contains(fullCode)) {
                    invalid = true;
                }

                // Caso 2: S_k cruza a fronteira entre S_a e S_b
                if (!invalid) {
                    for (int i = 1; i < len; i++) {
                        long left = encode(current, 0, i);
                        long right = encode(current, i, len);
                        if (suffixes.contains(left) && prefixes.contains(right)) {
                            invalid = true;
                            break;
                        }
                    }
                }

                if (invalid) {
                    System.out.println(current);
                    return;
                }
            }

            // Insere todos os prefixos de S_k
            for (int i = 1; i <= len; i++) {
                prefixes.add(encode(current, 0, i));
            }

            // Insere todos os sufixos de S_k
            for (int i = 0; i < len; i++) {
                suffixes.add(encode(current, i, len));
            }

            // Insere todas as substrings de S_k
            for (int i = 0; i < len; i++) {
                for (int j = i + 1; j <= len; j++) {
                    substrings.add(encode(current, i, j));
                }
            }
        }

        System.out.println("ok");
    }

    static class FastScanner {
        private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer tokenizer;

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}
